@dataclass
class Params:
    session_gap: float = 120.0      # s without a message that ends a session
    break_gap: float = 60.0         # s; a "break" for the endurance signal
    min_session: int = 30           # messages a session needs for timing analysis
    strong_session: int = 100       # messages a session needs to drive the account score
    max_lag: int = 150              # longest macro loop (in messages) searched for
    roll_window: int = 31           # intervals in the rolling window (message-level estimate)
    prior: float = 0.20             # prior probability that an active account is automated
    lock_min_pairs: int = 100       # paired messages needed to call two accounts "locked"
    handoff_window: float = 1800.0  # s after an account stops in which a successor is searched
    weights: dict = field(default_factory=dict)  # optional calibrated multipliers per signal
    bias: float | None = None                    # optional calibrated intercept


SIGNALS = [  # evidence groups (used for calibration weights)
    "regularity", "replay", "uniform_jitter", "clock_schedule", "human_rhythm",
    "endurance", "glued_text", "counter", "typos", "text_timing", "cycle_match",
    "lockstep", "fingerprint",
]


def logit(p):
    p = min(max(p, 1e-6), 1 - 1e-6)
    return math.log(p / (1 - p))


def sigmoid(x):
    return 1.0 / (1.0 + math.exp(-max(min(x, 50), -50)))


# --------------------------------------------------------------------------- #
# Loading (with a per-file cache)
# --------------------------------------------------------------------------- #
def _shift_day(day, n):
    return (dt.date.fromisoformat(day) + dt.timedelta(days=n)).isoformat()


def find_chat_files(paths, streams=None, date_from=None, date_to=None):
    """Accept the data dir, data/chat, a stream dir or single .jsonl files."""
    files = []
    for p in paths:
        p = os.path.expanduser(p)
        if os.path.isfile(p):
            files.append(p)
        elif os.path.isdir(os.path.join(p, "chat")):
            files += glob.glob(os.path.join(p, "chat", "*", "*.jsonl"))
        elif os.path.isdir(p):
            direct = glob.glob(os.path.join(p, "*.jsonl"))
            files += direct if direct else glob.glob(os.path.join(p, "*", "*.jsonl"))
        else:
            sys.exit(f"Not found: {p}")
    out = []
    for f in sorted(set(files)):
        sid = os.path.basename(os.path.dirname(f))
        day = os.path.splitext(os.path.basename(f))[0]
        if streams and sid not in streams:
            continue
        if re.fullmatch(r"\d{4}-\d{2}-\d{2}", day):
            # one day of margin either side: exact filtering happens on the timestamps
            if date_from and day < _shift_day(date_from, -1):
                continue
            if date_to and day > _shift_day(date_to, 1):
                continue
        out.append(f)
    return out


def _parse_file(path):
    authors = {}          # channelId -> index
    alist = []            # [channelId, name, is_owner, is_mod]
    ts, aidx, msgs = [], [], []
    seen = set()
    stream_id = None
    with open(path, "r", encoding="utf-8", errors="replace") as fh:
        for line in fh:
            line = line.strip()
            if not line:
                continue
            try:
                r = json.loads(line)
            except ValueError:
                continue
            mid = r.get("id")
            if mid in seen:
                continue
            seen.add(mid)
            a = r.get("author") or {}
            cid = a.get("channelId")
            t = r.get("timestamp")
            if not cid or t is None:
                continue
            stream_id = stream_id or r.get("stream_id")
            i = authors.get(cid)
            if i is None:
                i = authors[cid] = len(alist)
                alist.append([cid, a.get("name", ""), bool(a.get("isChatOwner")),
                              bool(a.get("isChatModerator"))])
            else:
                alist[i][1] = a.get("name", alist[i][1])
            ts.append(float(t) / 1000.0)
            aidx.append(i)
            msgs.append((r.get("message") or "")[:300])
    return {
        "stream_id": stream_id or os.path.basename(os.path.dirname(path)),
        "authors": alist,
        "ts": np.asarray(ts, dtype=np.float64),
        "aidx": np.asarray(aidx, dtype=np.int32),
        "msgs": msgs,
    }


def load_file(path, cache_dir):
    if cache_dir:
        st = os.stat(path)
        key = hashlib.sha1(f"{CACHE_VERSION}|{os.path.abspath(path)}|{st.st_size}|{st.st_mtime_ns}"
                           .encode()).hexdigest()
        cpath = os.path.join(cache_dir, key + ".pkl")
        if os.path.exists(cpath):
            try:
                with open(cpath, "rb") as fh:
                    return pickle.load(fh)
            except Exception:
                pass
        data = _parse_file(path)
        try:
            os.makedirs(cache_dir, exist_ok=True)
            tmp = cpath + ".tmp"
            with open(tmp, "wb") as fh:
                pickle.dump(data, fh, protocol=pickle.HIGHEST_PROTOCOL)
            os.replace(tmp, cpath)
        except OSError:
            pass
        return data
    return _parse_file(path)


class Stream:
    """All messages of one stream, sorted by time, grouped per author."""

    def __init__(self, sid, cooldown=None):
        self.sid = sid
        self.name, known_cd = KNOWN_STREAMS.get(sid, (sid, None))
        self.cooldown = cooldown or known_cd
        self.cid2g = {}
        self.authors = []      # [cid, name, owner, mod, set(names)]
        self._ts, self._g, self._m = [], [], []
        self.users = {}        # g -> (ts array, list of msgs)
        self._sessions = {}

    def add(self, fd):
        remap = np.empty(len(fd["authors"]), dtype=np.int32)
        for i, (cid, name, owner, mod) in enumerate(fd["authors"]):
            g = self.cid2g.get(cid)
            if g is None:
                g = self.cid2g[cid] = len(self.authors)
                self.authors.append([cid, name, owner, mod, {name}])
            else:
                a = self.authors[g]
                a[1] = name
                a[2] |= owner
                a[3] |= mod
                a[4].add(name)
            remap[i] = g
        self._ts.append(fd["ts"])
        self._g.append(remap[fd["aidx"]] if len(fd["aidx"]) else fd["aidx"])
        self._m.extend(fd["msgs"])

    def finalize(self):
        if not self._ts:
            return
        ts = np.concatenate(self._ts)
        g = np.concatenate(self._g)
        msgs = self._m
        order = np.lexsort((g, ts))
        ts, g = ts[order], g[order]
        # drop exact duplicates (same author, same timestamp) from overlapping files
        keep = np.ones(len(ts), dtype=bool)
        if len(ts) > 1:
            keep[1:] = ~((ts[1:] == ts[:-1]) & (g[1:] == g[:-1]))
        order, ts, g = order[keep], ts[keep], g[keep]
        by = np.argsort(g, kind="stable")
        gs = g[by]
        bounds = np.flatnonzero(np.diff(gs)) + 1
        for chunk in np.split(by, bounds):
            if len(chunk) == 0:
                continue
            gid = int(g[chunk[0]])
            self.users[gid] = (ts[chunk], [msgs[order[k]] for k in chunk])
        self._ts, self._g, self._m = [], [], []
        if self.cooldown is None:
            self.cooldown = self._estimate_cooldown()

    def _estimate_cooldown(self):
        ints = []
        for gid, (t, _) in self.users.items():
            if self.authors[gid][2] or self.authors[gid][3] or len(t) < 50:
                continue
            d = np.diff(t)
            ints.append(d[d > 0.2])
        if not ints:
            return 0.0
        return float(math.floor(np.percentile(np.concatenate(ints), 0.2)))

    def session_index(self, gap, min_n=50):
        """Arrays over all sessions of all accounts: gid, start, end, n, median gap, spread."""
        key = (gap, min_n)
        if not hasattr(self, "_sidx"):
            self._sidx = {}
        if key not in self._sidx:
            rows = []
            for g, (t, _) in self.users.items():
                for s_, e_ in self.sessions(g, gap):
                    if e_ - s_ < min_n:
                        continue
                    d = np.diff(t[s_:e_])
                    med = float(np.median(d))
                    rows.append((g, t[s_], t[e_ - 1], e_ - s_, med, iqr(d) / med if med else 1.0))
            arr = np.array(rows, dtype=float) if rows else np.zeros((0, 6))
            self._sidx[key] = dict(g=arr[:, 0].astype(int), start=arr[:, 1], end=arr[:, 2],
                                   n=arr[:, 3].astype(int), med=arr[:, 4], riqr=arr[:, 5])
        return self._sidx[key]

    def sessions(self, gid, gap):
        key = (gid, gap)
        if key not in self._sessions:
            t = self.users[gid][0]
            if len(t) == 0:
                self._sessions[key] = []
            else:
                cuts = np.flatnonzero(np.diff(t) > gap) + 1
                starts = np.concatenate(([0], cuts))
                ends = np.concatenate((cuts, [len(t)]))
                self._sessions[key] = list(zip(starts.tolist(), ends.tolist()))
        return self._sessions[key]


def load_streams(paths, streams=None, date_from=None, date_to=None, cache_dir=None,
                 cooldown=None, verbose=True, t_from=None, t_to=None):
    """date_from/date_to select files (YYYY-MM-DD); t_from/t_to (epoch s, end exclusive)
    cut the messages exactly."""
    files = find_chat_files(paths, streams, date_from, date_to)
    if not files:
        sys.exit("No chat files matched.")
    out = {}
    t0 = time.time()
    for k, f in enumerate(files, 1):
        fd = load_file(f, cache_dir)
        sid = fd["stream_id"]
        if streams and sid not in streams:
            continue
        if t_from is not None or t_to is not None:
            m = np.ones(len(fd["ts"]), dtype=bool)
            if t_from is not None:
                m &= fd["ts"] >= t_from
            if t_to is not None:
                m &= fd["ts"] < t_to
            if not m.all():
                keep = np.flatnonzero(m)
                fd = dict(fd, ts=fd["ts"][keep], aidx=fd["aidx"][keep],
                          msgs=[fd["msgs"][i] for i in keep])
            if len(fd["ts"]) == 0:
                continue
        if sid not in out:
            out[sid] = Stream(sid, cooldown)
        out[sid].add(fd)
        if verbose and (k % 25 == 0 or k == len(files)):
            print(f"\r  loading {k}/{len(files)} files ({time.time() - t0:.0f}s)",
                  end="", file=sys.stderr, flush=True)
    if verbose:
        print(file=sys.stderr)
    for s in out.values():
        s.finalize()
    if not out:
        sys.exit("No messages in the selected streams / time frame.")
    return out


# --------------------------------------------------------------------------- #
# Message content
# --------------------------------------------------------------------------- #
VOTE_RE = re.compile(r"\s*([^\W\d_]+)[^\w]*(\d[\d.,']{0,12})?")
GLUED_RE = re.compile(r"([^\W\d_]{2,})\s*\d+\1\s*\d+", re.IGNORECASE)


def parse_vote(msg):
    """-> (code, counter, extra_text). Replace this to plug in your own vote parser."""
    m = VOTE_RE.match(msg)
    if not m:
        return None, None, msg.strip()
    code = m.group(1).lower()
    counter = None
    if m.group(2):
        digits = re.sub(r"[.,']", "", m.group(2))
        if digits.isdigit() and len(digits) <= 9:
            counter = int(digits)
    extra = msg[m.end():].strip()
    return code, counter, extra


def has_text(extra):
    return sum(ch.isalpha() for ch in extra) >= 2


# --------------------------------------------------------------------------- #
# Small statistics helpers
# --------------------------------------------------------------------------- #
def iqr(x):
    q75, q25 = np.percentile(x, [75, 25])
    return float(q75 - q25)


def acf(x, max_lag):
    x = np.asarray(x, dtype=float)
    n = len(x)
    if n < 4:
        return np.zeros(max_lag + 1)
    lo, hi = np.percentile(x, [2, 98])
    x = np.clip(x, lo, hi)
    x = x - x.mean()
    var = float(np.dot(x, x))
    if var <= 0:
        return np.zeros(max_lag + 1)
    size = 1 << (2 * n - 1).bit_length()
    f = np.fft.rfft(x, size)
    r = np.fft.irfft(f * np.conj(f), size)[: max_lag + 1] / var
    # unbiased-ish: rescale by n/(n-k) so long lags are not shrunk towards 0
    k = np.arange(len(r))
    r = r * n / np.maximum(n - k, 1)
    out = np.zeros(max_lag + 1)
    out[: len(r)] = r
    return out


def moments(x):
    x = np.asarray(x, dtype=float)
    lo, hi = np.percentile(x, [1, 97])
    x = x[(x >= lo) & (x <= hi)]
    if len(x) < 20 or x.std() == 0:
        return 0.0, 0.0
    z = (x - x.mean()) / x.std()
    return float((z ** 3).mean()), float((z ** 4).mean() - 3.0)


def circ_spread(offsets, period):
    """Circular standard deviation (seconds) of offsets modulo period."""
    th = 2 * np.pi * np.asarray(offsets) / period
    R = abs(np.mean(np.exp(1j * th)))
    if R <= 1e-9:
        return float("inf"), 0.0
    return float(math.sqrt(-2 * math.log(R)) * period / (2 * math.pi)), float(R)


DISPLAY_TZ = None  # None = the computer's local time zone (the logger names its files in it)


def get_tz(name):
    if not name or name.lower() == "local":
        return None
    if name.upper() == "UTC":
        return dt.timezone.utc
    try:
        from zoneinfo import ZoneInfo
        return ZoneInfo(name)
    except Exception:
        sys.exit(f"Unknown time zone {name!r} (use e.g. Europe/Berlin, UTC or local)")


def parse_when(text, end=False, tz=None):
    """'2026-06-26', '2026-06-26 18:00', '2026-06-26T18:00:30' -> (epoch seconds, day string).
    A date alone means the whole day: start of day for --from, end of day for --to."""
    text = text.strip().replace("T", " ")
    for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M", "%Y-%m-%d"):
        try:
            d = dt.datetime.strptime(text, fmt)
            break
        except ValueError:
            continue
    else:
        sys.exit(f"Cannot read time {text!r}; use YYYY-MM-DD or 'YYYY-MM-DD HH:MM'")
    if fmt == "%Y-%m-%d" and end:
        d += dt.timedelta(days=1)
    d = d.replace(tzinfo=tz) if tz else d.astimezone()
    return d.timestamp(), text[:10]


def fmt_t(t, tz=None):
    return dt.datetime.fromtimestamp(t, tz or DISPLAY_TZ).strftime("%Y-%m-%d %H:%M")


# --------------------------------------------------------------------------- #
# Evidence functions: each returns (points, explanation)
# --------------------------------------------------------------------------- #
def ev_regularity(riqr, margin, n):
    near = margin < 0.6  # close to the slow-mode limit: a human reacting to the countdown can be tight
    if riqr < 0.006:
        pts, txt = 4.0, "machine precision (spread < 0.6 % of the interval)"
    elif riqr < 0.015:
        pts, txt = (2.0 if near else 3.0), "far tighter than human tapping (< 1.5 %)"
    elif riqr < 0.03:
        pts, txt = (0.8 if near else 2.0), "tighter than human free-running rhythm (< 3 %)"
    elif riqr < 0.05:
        pts, txt = (0.0 if near else 0.8), "very regular, at the edge of human ability"
    elif riqr < 0.08:
        pts, txt = 0.0, "regular, plausible for a focused human"
    elif riqr < 0.15:
        pts, txt = -1.0, "human-like variability"
    else:
        pts, txt = -2.0, "strongly varying, typical human"
    if near and pts > 0:
        txt += "; sits close to the cooldown, so partly reaction-limited"
    return pts * min(1.0, n / 150.0), txt


def ev_replay(r, max_lag, n):
    """r = averaged autocorrelation of intervals (index = lag).

    A replayed recording repeats its exact pauses every L messages, which gives sharp
    autocorrelation peaks at L, 2L, 3L ... ("comb").  Human tempo drift gives a smooth,
    decaying autocorrelation instead, so each peak must stand out against lags L-1/L+1."""
    r = np.nan_to_num(r)
    if n < 90:
        return 0.0, "too few intervals", None
    top = min(max_lag, n // 3)

    def prom(k):
        if k + 1 >= len(r) or k - 1 < 1:
            return None
        return float(r[k] - (r[k - 1] + r[k + 1]) / 2)

    best, bestL = 0.0, None
    for L in range(3, top + 1):
        p = prom(L)
        if p is None or p < 0.12 or r[L] <= best:
            continue
        best, bestL = float(r[L]), L
    if bestL is None:
        return 0.0, "no repeating timing pattern", None
    L = bestL
    sig = 3.5 / math.sqrt(max(n - L, 1))
    if best < max(0.2, sig):
        return 0.0, f"weak peak at {L} (r={best:.2f}), not significant", None
    has2 = 2 * L <= n // 2 and 2 * L + 1 < len(r)
    r2 = float(r[2 * L]) if has2 else None
    p2 = prom(2 * L) if has2 else None
    txt = f"timing repeats every {L} messages (r={best:.2f}" + (f", r@{2*L}={r2:.2f})" if has2 else ")")
    if has2 and L < 6:
        # very short loops are easy to confuse with alternating human habits: need 3L too
        has3 = 3 * L + 1 < len(r) and 3 * L <= n // 2
        p3 = prom(3 * L) if has3 else None
        if not (has3 and p2 >= 0.08 and p3 >= 0.08 and r[3 * L] >= 0.25):
            return 0.3, txt + " - short loop not confirmed at 2x and 3x the period", None
    if has2:
        if best >= 0.55 and r2 >= 0.35 and p2 >= 0.08:
            return 5.0, txt + " - replayed recording", L
        if best >= 0.35 and r2 >= 0.2 and p2 >= 0.06:
            return 3.0, txt + " - likely replayed recording", L
        if r2 >= 0.12 and p2 >= 0.04:
            return 1.5, txt + " - weak repetition", L
        return 0.3, txt + " - not confirmed at twice the period", None
    if best >= 0.6 and n >= 4 * L:
        return 2.5, txt + " - strong single peak (session too short to confirm)", L
    return 0.3, txt + " - single unconfirmed peak", None


def ev_uniform(skew, kurt, riqr, n):
    if n < 100:
        return 0.0, "too few intervals"
    if kurt < -0.9 and abs(skew) < 0.45:
        return 2.0, f"flat, hard-edged distribution (kurtosis {kurt:.2f}) - random.uniform-style jitter"
    if kurt < -0.6 and abs(skew) < 0.3 and riqr < 0.08:
        return 0.8, f"flattish distribution (kurtosis {kurt:.2f})"
    return 0.0, f"bell/right-skewed shape (skew {skew:.2f}, kurtosis {kurt:.2f})"


def ev_clock(r1, riqr, n):
    if n < 100:
        return 0.0, "too few intervals"
    if r1 <= -0.3 and riqr < 0.05:
        return 1.5, f"lag-1 autocorrelation {r1:.2f}: sends scheduled on a fixed clock (jitter cancels)"
    return 0.0, f"lag-1 autocorrelation {r1:.2f}"


def ev_rhythm(r1, r2, r3, n):
    if n < 150:
        return 0.0, "too few intervals"
    m = (r1 + r2 + r3) / 3
    if m > 0.25 and r1 > 0 and r3 > 0:
        return -1.0, f"slow tempo drift (mean r1..r3 = {m:.2f}), typical of humans"
    if m > 0.12 and r1 > 0:
        return -0.5, f"some tempo drift (mean r1..r3 = {m:.2f})"
    return 0.0, f"no human-like tempo drift (mean r1..r3 = {m:.2f})"


def ev_endurance(hours):
    if hours >= 3.0:
        return 1.5, f"{hours:.1f} h without a single break > 60 s"
    if hours >= 2.0:
        return 1.0, f"{hours:.1f} h without a break > 60 s"
    if hours >= 1.25:
        return 0.4, f"{hours:.1f} h without a break > 60 s"
    return 0.0, f"longest stretch without a break: {hours:.1f} h"


# --------------------------------------------------------------------------- #
# Analysis of one account on one stream ("track")
# --------------------------------------------------------------------------- #
def session_features(t, msgs, s, e, cd, P):
    d = np.diff(t[s:e])
    n = len(d)
    med = float(np.median(d))
    q = iqr(d)
    riqr = q / med if med > 0 else 1.0
    cap = med + max(4 * q, 0.5 * med)
    pauses = d > cap
    dc_ = np.where(pauses, med, d)
    succ = np.diff(dc_)
    # spread from successive differences: blind to slow tempo drift (e.g. a script whose
    # cycle slowly lengthens as the browser gets slower); 1.349 converts sd to IQR units
    local = 1.349 * 1.4826 * float(np.median(np.abs(succ - np.median(succ)))) / math.sqrt(2) / med \
        if len(succ) > 10 and med > 0 else riqr
    r = acf(dc_, P.max_lag * 2)
    r[max(n // 2, 1):] = np.nan          # lags beyond half the session are unreliable
    pause_period = None
    if pauses.sum() >= 4:
        pp = np.diff(np.flatnonzero(pauses))
        mc, cnt = Counter(pp.tolist()).most_common(1)[0]
        if cnt >= 3 and cnt >= 0.6 * len(pp):
            pause_period = int(mc)
    skew, kurt = moments(d)
    # longest stretch without a break
    brk = np.flatnonzero(d > P.break_gap)
    edges = np.concatenate(([0], brk + 1, [n + 1]))
    run = 0.0
    for a, b in zip(edges[:-1], edges[1:]):
        lo, hi = s + a, s + b - 1
        if hi > lo:
            run = max(run, t[min(hi, e - 1)] - t[lo])
    near_share = float(np.mean(d < cd + 0.35)) if cd else 0.0
    return dict(start=float(t[s]), end=float(t[e - 1]), n=e - s, median=med, iqr=q,
                riqr=riqr, local=local, margin=med - (cd or 0.0), acf=r, skew=skew, kurt=kurt,
                run_h=run / 3600.0, near_cd_share=near_share, pause_period=pause_period,
                n_pauses=int(pauses.sum()), p05=float(np.percentile(d, 5)),
                p95=float(np.percentile(d, 95)))


def content_repeat_share(votes, L):
    """Share of messages whose vote part equals the one L messages earlier."""
    if L is None or len(votes) <= L + 10:
        return None
    same = sum(1 for i in range(L, len(votes)) if votes[i] == votes[i - L])
    return same / (len(votes) - L)


def score_session(f, P, votes=None):
    ev = {}
    n = f["n"] - 1
    reg = min(f["riqr"], f["local"])
    pts_r, txt_r = ev_regularity(reg, f["margin"], n)
    txt_r += f" [spread {100*f['riqr']:.1f} %, beat-to-beat {100*f['local']:.1f} %]"
    if f["local"] < 0.6 * f["riqr"] and f["local"] < 0.03:
        txt_r += " - each gap almost equals the previous one while the tempo drifts slowly"
    ev["regularity"] = (pts_r, txt_r)
    pts, txt, L = ev_replay(f["acf"], P.max_lag, n)
    if L is not None and pts >= 1.5 and votes is not None:
        share = content_repeat_share(votes, L)
        f["content_repeat"] = share
        if share is not None and share < 0.3:
            # TinyTask replays keystrokes too, so the text must repeat with the timing.
            # A timing period with ever-new text (e.g. lag 10/100 with a rising counter)
            # comes from how the digits are typed, not from a replay.
            pts, txt, L = 0.3, txt.split(" - ")[0] + f" but the text does not repeat with it ({100*share:.0f} %) - typing effect, not a replay", None
        elif share is not None:
            txt += f"; text repeats too ({100*share:.0f} %)"
    ev["replay"] = (pts, txt)
    f["replay_lag"] = L
    ev["uniform_jitter"] = ev_uniform(f["skew"], f["kurt"], f["riqr"], n)
    ev["clock_schedule"] = ev_clock(float(f["acf"][1]), f["riqr"], n)
    ev["human_rhythm"] = ev_rhythm(*(float(f["acf"][k]) for k in (1, 2, 3)), n)
    ev["endurance"] = ev_endurance(f["run_h"])
    if f["local"] < 0.03 and ev["human_rhythm"][0] < 0:
        ev["human_rhythm"] = (0.0, ev["human_rhythm"][1] + " [ignored: drift is smooth, beat-to-beat spread is machine-like]")
    neutralise_for_replay(ev)
    total = sum(weighted(k, v[0], P) for k, v in ev.items())
    total = max(min(total, 7.0), -3.5)
    return ev, total


def neutralise_for_replay(ev):
    """A replayed recording reproduces the human pauses it was recorded with, so
    'human-looking' spread and drift say nothing once a replay is confirmed."""
    if ev["replay"][0] >= 3.0:
        for k in ("regularity", "human_rhythm"):
            if ev[k][0] < 0:
                ev[k] = (0.0, ev[k][1] + " [ignored: the replayed recording contains human pauses]")


def weighted(name, pts, P):
    return pts * P.weights.get(name, 1.0)


def counter_analysis(codes, counters):
    """Regularity of the per-message counters (bypass for YouTube's duplicate filter)."""
    dom = Counter(c for c in codes if c).most_common(1)
    dom = dom[0][0] if dom else None
    seq = [c for code, c in zip(codes, counters) if code == dom and c is not None]
    res = dict(dominant_code=dom, n_counted=len(seq), direction=0, steps=0, regular=0,
               irregular=0, wraps=0, cycle_len=None, cycle_share=0.0)
    if len(seq) < 20:
        return res
    steps = np.diff(np.asarray(seq, dtype=np.int64))
    direction = 1 if np.sum(steps == 1) >= np.sum(steps == -1) else -1
    res["direction"] = direction
    regular = int(np.sum(steps == direction))
    # a wrap = jump back to (near) the starting value of the counting direction
    big = np.abs(steps) >= 5
    wraps = big & (np.sign(steps) == -direction)
    res.update(steps=len(steps), regular=regular, wraps=int(wraps.sum()),
               irregular=int(len(steps) - regular - wraps.sum()))
    if wraps.sum() >= 3:
        pos = np.flatnonzero(wraps)
        lengths = np.diff(pos)
        if len(lengths):
            mc, cnt = Counter(lengths.tolist()).most_common(1)[0]
            res["cycle_len"] = int(mc)
            res["cycle_share"] = cnt / len(lengths)
    return res


def ev_counter(ca):
    n = ca["steps"]
    if n < 150:
        return 0.0, "too few counted votes"
    rate = ca["irregular"] / n
    txt = f"{ca['irregular']} irregular steps in {n} ({100*rate:.1f} %)"
    if ca["cycle_len"] and ca["cycle_share"] >= 0.6:
        txt += f"; counter restarts every {ca['cycle_len']} votes"
    if rate < 0.003:
        return 1.0, txt + " - flawless counting"
    if rate < 0.01:
        return 0.4, txt
    if rate > 0.05:
        return -1.0, txt + " - human-like slips"
    if rate > 0.02:
        return -0.5, txt
    return 0.0, txt


def typo_analysis(codes, dom):
    if not dom:
        return 0, 0
    freq = Counter(codes)
    n = len(codes)
    common = {c for c, k in freq.items() if k >= max(5, 0.03 * n)}
    typos = 0
    for c in codes:
        if not c or c == dom or c in common:
            continue
        if len(c) == len(dom) and sum(a != b for a, b in zip(c, dom)) == 1:
            typos += 1
        elif abs(len(c) - len(dom)) == 1 and (dom in c or c in dom):
            typos += 1
    return typos, n


def glued_analysis(msgs, codes, dom):
    hits = []
    for m, c in zip(msgs, codes):
        if GLUED_RE.search(m):
            hits.append(m)
        elif dom and c and c != dom and c.endswith(dom) and len(c) > len(dom) \
                and re.match(r"\s*[^\W\d_]+[^\w]*\d", m):
            hits.append(m)
    return hits


def ev_glued(hits):
    k = len(hits)
    if k == 0:
        return 0.0, "none"
    ex = ", ".join(repr(h[:30]) for h in hits[:4])
    note = " (a blind macro typing into an unsent message; a human pressing Enter during the cooldown can cause it too)"
    if k >= 3:
        return 1.5, f"{k} messages with a vote glued onto another ({ex})" + note
    if k == 2:
        return 1.0, f"2 glued messages ({ex})" + note
    return 0.5, f"1 glued message ({ex})"


def text_timing(t, msgs, sessions, cd):
    """Compare the interval before chatty messages with the interval before bare votes."""
    plain, extra = [], []
    for s, e in sessions:
        for i in range(s + 1, e):
            d = t[i] - t[i - 1]
            _, _, x = parse_vote(msgs[i])
            (extra if has_text(x) else plain).append(d)
    return np.asarray(plain), np.asarray(extra)


def ev_text_timing(plain, extra):
    if len(extra) < 10 or len(plain) < 50:
        return 0.0, f"{len(extra)} chat messages - too few to compare"
    mp, me = float(np.median(plain)), float(np.median(extra))
    delta = (me - mp) / mp
    r_extra = iqr(extra) / me if me else 1
    r_plain = iqr(plain) / mp if mp else 1
    txt = (f"{len(extra)} chat messages: median gap {me:.2f}s vs {mp:.2f}s for bare votes "
           f"({100*delta:+.1f} %), spread {100*r_extra:.1f} % vs {100*r_plain:.1f} %")
    if abs(delta) < 0.02 and r_extra < 0.04 and r_plain < 0.04:
        return 1.5, txt + " - typing never delays the send: a person chats, a machine sends"
    if delta > 0.12:
        return -1.0, txt + " - typing visibly delays sending"
    return 0.0, txt


def lockstep_analysis(stream, gid, P, min_share=0.6):
    """Find accounts whose messages keep a fixed phase to this account's (multi-tab macro)."""
    t = stream.users[gid][0]
    if len(t) < P.lock_min_pairs:
        return []
    idx = stream.session_index(P.session_gap)
    mine = idx["g"] == gid
    cand = set()
    for s0, e0 in zip(idx["start"][mine], idx["end"][mine]):
        ov = (~mine) & (idx["start"] < e0) & (idx["end"] > s0)
        cand.update(idx["g"][ov].tolist())
    d = np.diff(t)
    d = d[d < P.session_gap]
    if len(d) < 50:
        return []
    period = float(np.median(d))
    out = []
    for og in cand:
        ot = stream.users[og][0]
        # only look at the time range both accounts were active
        a, b = np.searchsorted(t, [ot[0] - period, ot[-1] + period])
        tt_all = t[a:b]
        if len(tt_all) < P.lock_min_pairs:
            continue
        k = np.searchsorted(ot, tt_all)
        lo = np.clip(k - 1, 0, len(ot) - 1)
        hi = np.clip(k, 0, len(ot) - 1)
        off_lo, off_hi = ot[lo] - tt_all, ot[hi] - tt_all
        off = np.where(np.abs(off_lo) < np.abs(off_hi), off_lo, off_hi)
        ok = np.abs(off) <= period / 2
        if ok.sum() < P.lock_min_pairs:
            continue
        tt, oo = tt_all[ok], off[ok]
        # split into co-active blocks; a macro restart may change the phase
        cuts = np.flatnonzero(np.diff(tt) > P.session_gap) + 1
        locked_n, total_n, blocks = 0, 0, []
        for bl in np.split(np.arange(len(tt)), cuts):
            if len(bl) < 30:
                continue
            seg_d = np.diff(tt[bl])
            seg_period = float(np.median(seg_d)) if len(seg_d) else period
            sd, R = circ_spread(oo[bl], seg_period)
            total_n += len(bl)
            if sd < min(0.6, 0.08 * seg_period):
                locked_n += len(bl)
                blocks.append(dict(start=float(tt[bl[0]]), end=float(tt[bl[-1]]), n=len(bl),
                                   offset=float(np.median(oo[bl])), spread=sd))
        if locked_n >= P.lock_min_pairs and locked_n >= min_share * total_n:
            out.append(dict(channel_id=stream.authors[og][0], name=stream.authors[og][1],
                            paired=int(locked_n), blocks=blocks))
    out.sort(key=lambda x: -x["paired"])
    return out


def handoff_analysis(stream, gid, sess_feats, dom_codes, P):
    """Accounts that take over right after this one stops (or vice versa), same country."""
    me = [f for f in sess_feats if f["n"] >= P.strong_session]
    if not me:
        return []
    dom = dom_codes.get(gid)
    idx = stream.session_index(P.session_gap, P.strong_session)
    same = np.array([(g != gid) and (dom_codes.get(int(g)) == dom) for g in idx["g"]], dtype=bool) \
        if len(idx["g"]) else np.zeros(0, dtype=bool)
    out = []
    W = P.handoff_window
    for f in me:
        after = same & (idx["start"] - f["end"] >= 0) & (idx["start"] - f["end"] <= W)
        before = same & (f["start"] - idx["end"] >= 0) & (f["start"] - idx["end"] <= W)
        for mask, rel in ((after, "takes over after"), (before, "handed over to this account after")):
            for j in np.flatnonzero(mask):
                og = int(idx["g"][j])
                omed, oriqr = float(idx["med"][j]), float(idx["riqr"][j])
                same_fp = (abs(omed - f["median"]) / f["median"] < 0.004
                           and oriqr < 0.05 and f["riqr"] < 0.05)
                gap = idx["start"][j] - f["end"] if rel.startswith("takes") else f["start"] - idx["end"][j]
                out.append(dict(channel_id=stream.authors[og][0], name=stream.authors[og][1],
                                relation=rel, gap_s=float(gap), their_median=omed, my_median=f["median"],
                                same_fingerprint=bool(same_fp),
                                at=f["end"] if rel.startswith("takes") else f["start"]))
    out.sort(key=lambda x: (not x["same_fingerprint"], x["at"]))
    return out


def rolling_flags(t, s, e, thr_far, thr_near, cd, w):
    """Mark messages that sit inside a window of machine-like regularity."""
    d = np.diff(t[s:e])
    n = len(d)
    flags = np.zeros(e - s, dtype=bool)
    if n < w:
        return flags
    win = np.lib.stride_tricks.sliding_window_view(d, w)
    q25, med, q75 = np.percentile(win, [25, 50, 75], axis=1)
    thr = np.where((med - (cd or 0)) < 0.6, thr_near, thr_far) if cd else thr_far
    reg = (q75 - q25) / np.maximum(med, 1e-9) < thr
    # window i is centred on interval i + w//2; edge intervals inherit the nearest window
    h = w // 2
    reg_c = np.empty(n, dtype=bool)
    reg_c[h:h + len(reg)] = reg
    reg_c[:h] = reg[0]
    reg_c[h + len(reg):] = reg[-1]
    flags[:-1] |= reg_c
    flags[1:] |= reg_c
    return flags


def analyze_track(stream, gid, P, dom_codes=None, deep=True):
    t, msgs = stream.users[gid]
    cd = stream.cooldown or 0.0
    cid, name = stream.authors[gid][0], stream.authors[gid][1]
    parsed = [parse_vote(m) for m in msgs]
    codes = [p[0] for p in parsed]
    counters = [p[1] for p in parsed]
    sessions = stream.sessions(gid, P.session_gap)

    res = dict(stream_id=stream.sid, stream=stream.name, cooldown=cd, channel_id=cid,
               name=name, other_names=sorted(n for n in stream.authors[gid][4] if n != name),
               moderator=stream.authors[gid][3], owner=stream.authors[gid][2],
               n_messages=len(t), first=float(t[0]), last=float(t[-1]))

    # --- per-session timing evidence
    feats = []
    for s, e in sessions:
        if e - s >= P.min_session:
            f = session_features(t, msgs, s, e, cd, P)
            votes = [(parsed[i][0], parsed[i][1]) for i in range(s + 1, e)]
            f["ev"], f["points"] = score_session(f, P, votes)
            f["slice"] = (s, e)
            feats.append(f)
    # sessions too short for the blind search: test the loop length already found
    loops = Counter(f["replay_lag"] for f in feats if f.get("replay_lag") and f["ev"]["replay"][0] >= 3.0)
    if loops:
        Lk = loops.most_common(1)[0][0]
        for f in feats:
            if f["ev"]["replay"][0] >= 3.0 or f["n"] < 2 * Lk + 10:
                continue
            rr = np.nan_to_num(f["acf"])
            sv = [(parsed[i][0], parsed[i][1]) for i in range(f["slice"][0] + 1, f["slice"][1])]
            cs = content_repeat_share(sv, Lk)
            if Lk + 1 < len(rr) and rr[Lk] >= 0.3 and rr[Lk] - (rr[Lk - 1] + rr[Lk + 1]) / 2 >= 0.1 \
                    and (cs is None or cs >= 0.3):
                f["ev"]["replay"] = (3.0, f"matches this account's known {Lk}-message loop (r={rr[Lk]:.2f})")
                f["replay_lag"] = Lk
                neutralise_for_replay(f["ev"])
                f["points"] = max(min(sum(weighted(k, v[0], P) for k, v in f["ev"].items()), 7.0), -3.5)
    res["sessions"] = feats
    res["n_sessions_total"] = len(sessions)

    # aggregated autocorrelation over sessions (for the report and cycle matching)
    if feats:
        A = np.vstack([f["acf"] for f in feats])
        W = np.where(np.isnan(A), 0.0, np.array([f["n"] for f in feats], dtype=float)[:, None])
        acf_avg = np.nansum(np.nan_to_num(A) * W, axis=0) / np.maximum(W.sum(axis=0), 1)
    else:
        acf_avg = np.zeros(P.max_lag * 2 + 1)
    res["acf"] = acf_avg

    # --- account-wide content evidence
    acc = {}
    ca = counter_analysis(codes, counters)
    res["counter"] = ca
    acc["counter"] = ev_counter(ca)
    dom = ca["dominant_code"]
    ty, nmsg = typo_analysis(codes, dom)
    res["typos"] = ty
    if ty >= 3 and ty / max(nmsg, 1) >= 0.004:
        acc["typos"] = (-0.8, f"{ty} mistyped country codes - human slips")
    elif ty >= 1:
        acc["typos"] = (-0.3, f"{ty} mistyped country code(s)")
    else:
        acc["typos"] = (0.0, "no mistyped codes")
    glued = glued_analysis(msgs, codes, dom)
    res["glued_examples"] = glued[:10]
    acc["glued_text"] = ev_glued(glued)
    plain, extra = text_timing(t, msgs, [f["slice"] for f in feats], cd)
    res["chat_messages"] = int(len(extra))
    acc["text_timing"] = ev_text_timing(plain, extra)

    # cycle match: counter restart period == timing repeat period
    lags = [f.get("replay_lag") for f in feats if f.get("replay_lag")]
    cyc = ca["cycle_len"] if ca["cycle_share"] >= 0.6 else None
    if cyc and lags and any(abs(L - cyc) <= 1 or (L % cyc == 0) for L in lags):
        acc["cycle_match"] = (1.5, f"counter restarts every {cyc} votes and timing repeats with the same period")
    elif cyc:
        acc["cycle_match"] = (0.3, f"counter restarts every {cyc} votes (timing does not repeat with it)")
    else:
        acc["cycle_match"] = (0.0, "no counter cycle")
    if acc["cycle_match"][0] >= 1.5 or loops:
        for k in ("counter", "typos"):
            if acc[k][0] < 0:
                acc[k] = (0.0, acc[k][1] + " [ignored: slips can be part of a replayed recording]")

    # --- cross-account evidence
    if deep:
        locks = lockstep_analysis(stream, gid, P)
        res["locked_with"] = locks
        if locks:
            nm = ", ".join(f"{x['name']} ({x['paired']} msgs)" for x in locks[:4])
            acc["lockstep"] = (2.5, f"moves in fixed phase with {nm}: same macro driving several tabs")
        else:
            acc["lockstep"] = (0.0, "no account moves in lockstep")
        if dom_codes is not None:
            ho = handoff_analysis(stream, gid, feats, dom_codes, P)
            res["handoffs"] = ho
            fps = [h for h in ho if h["same_fingerprint"]]
            if fps:
                acc["fingerprint"] = (1.0, "successor/predecessor with identical timing fingerprint: "
                                      + ", ".join(sorted({h["name"] for h in fps})[:4]))
            else:
                acc["fingerprint"] = (0.0, f"{len(ho)} hand-over(s), none with identical timing" if ho else "no hand-overs")
    res["account_evidence"] = acc

    # --- daily volume (info)
    if len(t) > 1:
        j = np.searchsorted(t, t + 86400.0)
        res["max_24h"] = int((j - np.arange(len(t))).max())
    else:
        res["max_24h"] = len(t)

    # --- combine
    prior = P.bias if P.bias is not None else logit(P.prior)
    acc_pts = sum(weighted(k, v[0], P) for k, v in acc.items())
    acc_pts = max(min(acc_pts, 6.0), -3.0)
    strong = [f for f in feats if f["n"] >= P.strong_session]
    if strong:
        best = max(strong, key=lambda f: f["points"])
        timing = best["points"]
        res["driving_session"] = feats.index(best)
    elif feats:
        timing = float(np.average([f["points"] for f in feats], weights=[f["n"] for f in feats]))
        res["driving_session"] = None
    else:
        timing = 0.0
        res["driving_session"] = None
    res["timing_points"] = timing
    res["account_points"] = acc_pts
    res["logodds"] = prior + timing + acc_pts
    res["probability"] = sigmoid(res["logodds"])

    # --- per-session probability and message-level automated share
    lock_blocks = [b for x in res.get("locked_with", []) for b in x["blocks"]]
    flagged = np.zeros(len(t), dtype=bool)
    for f in feats:
        s, e = f["slice"]
        f["probability"] = sigmoid(prior + f["points"] + 0.5 * acc_pts)
        if f["ev"]["replay"][0] >= 3.0:
            flagged[s:e] = True
        else:
            flagged[s:e] |= rolling_flags(t, s, e, 0.03, 0.015, cd, P.roll_window)
        for b in lock_blocks:
            flagged[s:e] |= (t[s:e] >= b["start"]) & (t[s:e] <= b["end"])
    res["automated_share"] = float(flagged.mean()) if len(t) else 0.0
    res["flags"] = flagged
    return res


def verdict(p):
    if p >= 0.95:
        return "very likely automated"
    if p >= 0.80:
        return "likely automated"
    if p >= 0.50:
        return "leaning automated"
    if p >= 0.25:
        return "inconclusive"
    if p >= 0.08:
        return "likely manual"
    return "very likely manual"


def dominant_codes(stream):
    out = {}
    for g, (t, msgs) in stream.users.items():
        c = Counter(parse_vote(m)[0] for m in msgs[:2000])
        c.pop(None, None)
        out[g] = c.most_common(1)[0][0] if c else None
    return out


# --------------------------------------------------------------------------- #
# Reporting
# --------------------------------------------------------------------------- #
def print_report(user_label, tracks, P, tz=None, file=sys.stdout):
    w = lambda s="": print(s, file=file)
    if not tracks:
        w(f"No messages found for {user_label}.")
        return
    big = [r for r in tracks if r["n_messages"] >= 100]
    best = max(big, key=lambda r: r["probability"]) if big else max(tracks, key=lambda r: r["n_messages"])
    names = sorted({r["name"] for r in tracks} | {n for r in tracks for n in r["other_names"]})
    w("=" * 78)
    w(f"Account   {', '.join(names)}   ({tracks[0]['channel_id']})")
    w(f"Overall   P(automated voting) = {best['probability']:.3f}  ->  {verdict(best['probability']).upper()}"
      f"   [based on {best['stream']}]")
    if not big:
        w(f"          INSUFFICIENT DATA: no stream has 100+ messages from this account; the number is mostly the prior.")
    w("=" * 78)
    for r in sorted(tracks, key=lambda r: -r["n_messages"]):
        w()
        w(f"--- {r['stream']} ({r['stream_id']}), slow mode {r['cooldown']:.0f}s "
          + ("[MODERATOR - slow mode does not apply] " if r["moderator"] else ""))
        w(f"    {r['n_messages']} messages, {fmt_t(r['first'], tz)} -> {fmt_t(r['last'], tz)}, "
          f"max {r['max_24h']} in 24h, {r['chat_messages']} with chat text")
        w(f"    P(automated) = {r['probability']:.3f} ({verdict(r['probability'])}); "
          f"est. share of messages sent by automation: {100*r['automated_share']:.0f} %")
        w(f"    log-odds: prior {logit(P.prior) if P.bias is None else P.bias:+.2f}  "
          f"timing {r['timing_points']:+.2f}  account {r['account_points']:+.2f}")
        ds = r.get("driving_session")
        if ds is not None:
            f = r["sessions"][ds]
            w(f"    Timing evidence (strongest session {fmt_t(f['start'], tz)}, {f['n']} msgs):")
            for k, (pts, txt) in f["ev"].items():
                w(f"      {pts:+5.2f}  {k:<15} {txt}")
        elif r["sessions"]:
            w("    Timing evidence: no session with enough messages; using an average")
        w("    Account evidence:")
        for k, (pts, txt) in r["account_evidence"].items():
            w(f"      {pts:+5.2f}  {k:<15} {txt}")
        if r.get("locked_with"):
            for x in r["locked_with"][:5]:
                b = max(x["blocks"], key=lambda b: b["n"])
                w(f"      lockstep: {x['name']} ({x['channel_id']}): offset {b['offset']:+.2f}s "
                  f"+/- {b['spread']:.2f}s over {x['paired']} msgs")
        if r.get("handoffs"):
            w("    Hand-overs (same country, within 30 min):")
            for h in r["handoffs"][:8]:
                fp = "  SAME TIMING FINGERPRINT" if h["same_fingerprint"] else ""
                w(f"      {fmt_t(h['at'], tz)}  {h['name']} {h['relation']} {h['gap_s']/60:.0f} min "
                  f"(median gap {h['their_median']:.2f}s vs {h['my_median']:.2f}s){fp}")
        if r["sessions"]:
            w("    Sessions (>= %d msgs):" % P.min_session)
            w("      start              end    msgs  median   spread  beat  replay  P(auto)")
            for f in r["sessions"][:40]:
                L = f.get("replay_lag")
                w(f"      {fmt_t(f['start'], tz)}  {dt.datetime.fromtimestamp(f['end'], tz or DISPLAY_TZ).strftime('%H:%M')}"
                  f"  {f['n']:5d}  {f['median']:6.2f}s  {100*f['riqr']:5.1f} % {100*f['local']:4.1f} %  "
                  f"{(str(L) if L else '-'):>6}  {f['probability']:.2f}")
            if len(r["sessions"]) > 40:
                w(f"      ... {len(r['sessions']) - 40} more sessions (see --json)")
    w()
    w("Spread = interquartile range of the gaps / median gap; beat = the same measured from one gap")
    w("to the next (ignores slow tempo drift). Humans rarely go below ~5 % on either.")
    w("This is a likelihood from chat timing and text only, not proof. Check the evidence lines.")


def track_json(r):
    out = {k: v for k, v in r.items() if k not in ("acf", "flags", "sessions") and not k.startswith("_")}
    out["verdict"] = verdict(r["probability"])
    out["acf_lag1_10"] = [round(float(x), 3) for x in r["acf"][1:11]]
    out["sessions"] = []
    for f in r["sessions"]:
        g = {k: v for k, v in f.items() if k not in ("acf", "slice", "ev")}
        g["evidence"] = {k: {"points": v[0], "why": v[1]} for k, v in f["ev"].items()}
        out["sessions"].append(g)
    out["account_evidence"] = {k: {"points": v[0], "why": v[1]} for k, v in r["account_evidence"].items()}
    return out


def _json_default(o):
    if isinstance(o, np.ndarray):
        return o.tolist()
    if isinstance(o, (np.integer,)):
        return int(o)
    if isinstance(o, (np.floating,)):
        return None if np.isnan(o) else float(o)
    if isinstance(o, set):
        return sorted(o)
    return str(o)


def plot_tracks(tracks, path):
    try:
        import matplotlib
        matplotlib.use("Agg")
        import matplotlib.pyplot as plt
    except ImportError:
        print("matplotlib not installed; skipping --plot", file=sys.stderr)
        return
    rows = [r for r in tracks if r["sessions"]]
    if not rows:
        return
    fig, axes = plt.subplots(len(rows), 4, figsize=(18, 3.6 * len(rows)), squeeze=False)
    for ax, r in zip(axes, rows):
        P = r["sessions"]
        d_all, t_all, c_all = [], [], []
        for f in P:
            s, e = f["slice"]
            ts = r["_t"][s:e]
            d_all.append(np.diff(ts))
            t_all.append(ts[1:])
            c_all.append(r["flags"][s + 1:e])
        d = np.concatenate(d_all)
        tt = np.concatenate(t_all)
        cf = np.concatenate(c_all)
        hi = np.percentile(d, 99)
        ax[0].hist(d[d <= hi], bins=np.arange(d.min(), hi + 0.05, 0.05), color="#3b6ea5")
        ax[0].axvline(r["cooldown"], color="#c0392b", lw=1, ls="--")
        ax[0].set_title(f"{r['name']} - {r['stream']}: gap histogram (0.05 s bins)", fontsize=9)
        ax[0].set_xlabel("seconds between messages")
        lags = np.arange(1, len(r["acf"]))
        ax[1].bar(lags, r["acf"][1:], width=1.0, color="#3b6ea5")
        ax[1].set_title("autocorrelation of gaps (replay -> sharp peaks)", fontsize=9)
        ax[1].set_xlabel("lag (messages)")
        ax[1].set_ylim(-0.6, 1)
        nz = np.flatnonzero(r["acf"][1:])
        ax[1].set_xlim(0, (nz[-1] + 2) if len(nz) else 10)
        hrs = (tt - tt[0]) / 3600
        ax[2].scatter(hrs[~cf], np.clip(d[~cf], 0, hi), s=2, color="#3b6ea5", label="manual-looking")
        ax[2].scatter(hrs[cf], np.clip(d[cf], 0, hi), s=2, color="#c0392b", label="flagged automated")
        ax[2].legend(fontsize=7, markerscale=4)
        ax[2].set_title("gap over time", fontsize=9)
        ax[2].set_xlabel("hours since first analysed message")
        ctr = [parse_vote(m)[1] for m in r["_m"]]
        ax[3].plot([c if c is not None else np.nan for c in ctr], lw=0.6, color="#3b6ea5")
        ax[3].set_title("vote counter by message", fontsize=9)
        ax[3].set_xlabel("message #")
    fig.tight_layout()
    fig.savefig(path, dpi=110)
    print(f"plot written to {path}", file=sys.stderr)


# --------------------------------------------------------------------------- #
# Modes
# --------------------------------------------------------------------------- #
def resolve_user(streams, query):
    q = query.strip()
    m = re.search(r"(UC[\w-]{22})", q)
    if m:
        cid = m.group(1)
        return {cid}
    ql = q.lower().lstrip("@")
    hits = set()
    for s in streams.values():
        for a in s.authors:
            if any(n.lower().lstrip("@") == ql for n in a[4]):
                hits.add(a[0])
    return hits


def run_user(streams, query, P, args):
    cids = resolve_user(streams, query)
    if not cids:
        sys.exit(f"No account matching {query!r} in the selected data.")
    if len(cids) > 1:
        print(f"Note: {query!r} matches {len(cids)} channels: {', '.join(sorted(cids))}", file=sys.stderr)
    results = {}
    for cid in sorted(cids):
        tracks = []
        for s in streams.values():
            g = s.cid2g.get(cid)
            if g is None or g not in s.users or len(s.users[g][0]) < 2:
                continue
            dc = dominant_codes(s)
            r = analyze_track(s, g, P, dom_codes=dc)
            r["_t"], r["_m"] = s.users[g]
            tracks.append(r)
        print_report(query, tracks, P, tz=None)
        results[cid] = tracks
        if args.plot and tracks:
            base, ext = os.path.splitext(args.plot)
            many = len(cids) > 1 or len(args.user) > 1
            plot_tracks(tracks, f"{base}_{tracks[0]['name'].lstrip('@')}{ext or '.png'}" if many else args.plot)
    return results


def all_tracks(streams, P, min_messages, deep=True):
    out = []
    for s in streams.values():
        dc = dominant_codes(s)
        gids = [g for g, (t, _) in s.users.items()
                if len(t) >= min_messages and not s.authors[g][2]]
        for k, g in enumerate(gids, 1):
            out.append(analyze_track(s, g, P, dom_codes=dc, deep=deep))
            if sys.stderr.isatty():
                print(f"\r  {s.name}: {k}/{len(gids)} accounts", end="", file=sys.stderr, flush=True)
        if sys.stderr.isatty():
            print(file=sys.stderr)
    return out


def run_rank(streams, P, args):
    tracks = all_tracks(streams, P, args.min_messages)
    tracks.sort(key=lambda r: -r["probability"])
    rows = []
    for r in tracks:
        sig = sorted(((v[0], k) for k, v in r["account_evidence"].items()), reverse=True)
        ds = r.get("driving_session")
        if ds is not None:
            sig += [(v[0], k) for k, v in r["sessions"][ds]["ev"].items()]
        top = [f"{k}{p:+.1f}" for p, k in sorted(sig, reverse=True) if abs(p) >= 0.5][:5]
        rows.append(dict(probability=round(r["probability"], 4), verdict=verdict(r["probability"]),
                         name=r["name"], channel_id=r["channel_id"], stream=r["stream"],
                         messages=r["n_messages"], automated_share=round(r["automated_share"], 3),
                         locked_with="; ".join(x["name"] for x in r.get("locked_with", [])),
                         same_fingerprint_handoffs="; ".join(sorted({h["name"] for h in r.get("handoffs", [])
                                                                     if h["same_fingerprint"]})),
                         top_signals=" ".join(top)))
    print(f"\n{'P':>6}  {'auto%':>5}  {'msgs':>6}  {'stream':<16} name / top signals")
    for x in rows[: args.top]:
        print(f"{x['probability']:6.3f}  {100*x['automated_share']:5.0f}  {x['messages']:6d}  "
              f"{x['stream'][:16]:<16} {x['name']}  [{x['top_signals']}]")
    if args.csv:
        with open(args.csv, "w", newline="", encoding="utf-8") as fh:
            wr = csv.DictWriter(fh, fieldnames=list(rows[0].keys()) if rows else ["probability"])
            wr.writeheader()
            wr.writerows(rows)
        print(f"CSV written to {args.csv}", file=sys.stderr)
    if args.json:
        with open(args.json, "w", encoding="utf-8") as fh:
            json.dump([track_json(r) for r in tracks], fh, ensure_ascii=False, indent=1, default=_json_default)


def run_bots(streams, P, args, window):
    """List every account whose P(automated) reaches the threshold."""
    thr = args.bots
    tracks = all_tracks(streams, P, args.min_messages)
    tracks.sort(key=lambda r: (r["stream"], -r["probability"]))
    hits = [r for r in tracks if r["probability"] >= thr]
    borderline = [r for r in tracks if 0.5 <= r["probability"] < thr]
    print()
    print(f"Likely bots (P >= {thr:.2f}) - {window}")
    print(f"{len(hits)} of {len(tracks)} accounts with >= {args.min_messages} messages in this window"
          + (f"; {len(borderline)} more between 0.50 and {thr:.2f}" if borderline else ""))
    rows = []
    for sname in sorted({r["stream"] for r in tracks}):
        sh = [r for r in hits if r["stream"] == sname]
        if not sh:
            continue
        cd = sh[0]["cooldown"]
        print(f"\n=== {sname} (slow mode {cd:.0f}s): {len(sh)} account(s)")
        print(f"{'P':>6} {'auto%':>5} {'msgs':>6}  {'active (first -> last)':<36} {'country':<8} name")
        for r in sh:
            ev = dict(r["account_evidence"])
            ds = r.get("driving_session")
            if ds is not None:
                ev.update(r["sessions"][ds]["ev"])
            top = [f"{k}{p:+.1f}" for k, (p, _) in sorted(ev.items(), key=lambda kv: -kv[1][0]) if p >= 0.5][:4]
            locked = sorted({x["name"] for x in r.get("locked_with", [])})
            fps = sorted({h["name"] for h in r.get("handoffs", []) if h["same_fingerprint"]})
            first, last = fmt_t(r["first"]), fmt_t(r["last"])
            if first[:10] == last[:10]:
                last = last[11:]
            print(f"{r['probability']:6.3f} {100*r['automated_share']:5.0f} {r['n_messages']:6d}  "
                  f"{first + ' -> ' + last:<36} {str(r['counter']['dominant_code'] or '-'):<8} {r['name']}")
            print(f"{'':21}why: {' '.join(top) or '-'}")
            if locked:
                print(f"{'':21}lockstep with: {', '.join(locked[:6])}")
            if fps:
                print(f"{'':21}same timing as: {', '.join(fps[:6])}")
            rows.append(dict(stream=r["stream"], stream_id=r["stream_id"], probability=round(r["probability"], 4),
                             verdict=verdict(r["probability"]), name=r["name"], channel_id=r["channel_id"],
                             country=r["counter"]["dominant_code"], messages=r["n_messages"],
                             automated_share=round(r["automated_share"], 3),
                             first=fmt_t(r["first"]), last=fmt_t(r["last"]),
                             locked_with="; ".join(locked), same_timing_as="; ".join(fps),
                             top_signals=" ".join(top)))
    if borderline and args.show_borderline:
        print(f"\n--- borderline (0.50 <= P < {thr:.2f})")
        for r in sorted(borderline, key=lambda r: -r["probability"]):
            print(f"{r['probability']:6.3f} {100*r['automated_share']:5.0f} {r['n_messages']:6d}  {r['stream'][:16]:<16} {r['name']}")
    print("\nauto% = estimated share of the account's messages in this window sent by automation.")
    print("Check single accounts with --user NAME (add --plot) before acting on this list.")
    if args.csv:
        with open(args.csv, "w", newline="", encoding="utf-8") as fh:
            fields = list(rows[0].keys()) if rows else ["stream", "probability", "name", "channel_id"]
            wr = csv.DictWriter(fh, fieldnames=fields)
            wr.writeheader()
            wr.writerows(rows)
        print(f"CSV written to {args.csv}", file=sys.stderr)
    if args.json:
        with open(args.json, "w", encoding="utf-8") as fh:
            json.dump(dict(window=window, threshold=thr, accounts=[track_json(r) for r in hits]),
                      fh, ensure_ascii=False, indent=1, default=_json_default)
        print(f"JSON written to {args.json}", file=sys.stderr)


def evidence_vector(r):
    """Per-signal points of a track (timing from the driving session)."""
    v = dict.fromkeys(SIGNALS, 0.0)
    for k, (p, _) in r["account_evidence"].items():
        v[k] = p
    ds = r.get("driving_session")
    if ds is not None:
        for k, (p, _) in r["sessions"][ds]["ev"].items():
            v[k] = p
    return np.array([v[k] for k in SIGNALS])


def run_calibrate(streams, P, args):
    labels = {}
    with open(args.calibrate, newline="", encoding="utf-8") as fh:
        for row in csv.reader(fh):
            if not row or row[0].startswith("#") or row[0].lower() in ("user", "channel_id", "account"):
                continue
            labels[row[0].strip()] = 1.0 if row[1].strip().lower() in ("1", "bot", "auto", "automated", "yes") else 0.0
    X, y, who = [], [], []
    P0 = Params(**{**P.__dict__, "weights": {}, "bias": None})
    for q, lab in labels.items():
        cids = resolve_user(streams, q)
        for cid in cids:
            for s in streams.values():
                g = s.cid2g.get(cid)
                if g is None or len(s.users.get(g, ([],))[0]) < 100:
                    continue
                r = analyze_track(s, g, P0, dom_codes=dominant_codes(s))
                X.append(evidence_vector(r))
                y.append(lab)
                who.append(f"{r['name']}@{r['stream']}")
    if len(X) < 6:
        sys.exit(f"Only {len(X)} labelled tracks found; need at least 6 (better 30+).")
    X, y = np.vstack(X), np.array(y)

    def fit(Xa, ya, lam=1.0, iters=4000, lr=0.05):
        w = np.ones(Xa.shape[1])
        b = logit(P.prior)
        for _ in range(iters):
            z = np.clip(Xa @ w + b, -30, 30)
            p = 1 / (1 + np.exp(-z))
            gw = Xa.T @ (p - ya) / len(ya) + lam * (w - 1.0) / len(ya)  # shrink towards hand-set weights
            gb = float(np.mean(p - ya))
            w -= lr * gw
            b -= lr * gb
            w = np.clip(w, 0.0, 3.0)
        return w, b

    w, b = fit(X, y)
    # leave-one-out check
    correct, ll = 0, 0.0
    for i in range(len(y)):
        m = np.arange(len(y)) != i
        wi, bi = fit(X[m], y[m], iters=1500)
        p = 1 / (1 + math.exp(-float(np.clip(X[i] @ wi + bi, -30, 30))))
        correct += int((p >= 0.5) == (y[i] == 1))
        ll += -math.log(max(p if y[i] == 1 else 1 - p, 1e-9))
    print(f"{len(y)} labelled tracks ({int(y.sum())} automated / {int(len(y) - y.sum())} manual)")
    print(f"leave-one-out accuracy {correct}/{len(y)} = {correct/len(y):.2f}, mean log-loss {ll/len(y):.3f}")
    print("weights (1.0 = hand-set default):")
    for k, wk in zip(SIGNALS, w):
        print(f"  {k:<15} {wk:.2f}")
    print(f"  bias            {b:+.2f}")
    if args.save_weights:
        with open(args.save_weights, "w") as fh:
            json.dump({"weights": dict(zip(SIGNALS, map(float, w))), "bias": float(b),
                       "n_labels": int(len(y))}, fh, indent=1)
        print(f"weights saved to {args.save_weights}")


# --------------------------------------------------------------------------- #
# Self-test with simulated accounts
# --------------------------------------------------------------------------- #
def _simulate(kind, rng, n=800, cd=12.0, start=1.78e9):
    t = [start]
    msgs = []
    if kind == "human":
        tempo = 2.5
        i = 1
        while len(t) < n:
            tempo = 0.9 * tempo + 0.1 * rng.uniform(1.0, 6.0)          # slow drift
            gap = cd + tempo * rng.gamma(2.0, 0.5) + (rng.exponential(60) if rng.random() < 0.01 else 0)
            t.append(t[-1] + gap)
        for k in range(n):
            c = k + 1 + (rng.integers(1, 3) if rng.random() < 0.03 else 0)
            code = "de" if rng.random() > 0.01 else "ed"
            msgs.append(f"{code} {c}" + (" lol" if rng.random() < 0.05 else ""))
    elif kind == "sleep_loop":
        for k in range(1, n):
            t.append(t[-1] + 14.4 + rng.normal(0, 0.012))
        msgs = [f"de {k+1}" for k in range(n)]
    elif kind == "uniform_jitter":
        for k in range(1, n):
            t.append(t[-1] + rng.uniform(13.0, 16.0))
        msgs = [f"de {k+1}" for k in range(n)]
    elif kind == "tinytask":
        rec = cd + 1.0 + rng.gamma(2.0, 1.5, size=19)                    # recorded human pauses
        for k in range(1, n):
            t.append(t[-1] + rec[k % 19] + rng.normal(0, 0.04))
        msgs = [f"hr{(k % 19) + 2}" for k in range(n)]
    return np.array(t), msgs


def run_selftest():
    rng = np.random.default_rng(7)
    s = Stream("selftest", cooldown=12.0)
    s.name = "simulated"
    kinds = ["human", "human", "sleep_loop", "uniform_jitter", "tinytask"]
    for i, kind in enumerate(kinds):
        t, m = _simulate(kind, rng, start=1.78e9 + i * 50000)
        s.add({"authors": [[f"UC{'x'*21}{i}", f"{kind}_{i}", False, False]],
               "ts": t, "aidx": np.zeros(len(t), dtype=np.int32), "msgs": m})
    s.finalize()
    P = Params()
    dc = dominant_codes(s)
    ok = True
    for g in s.users:
        r = analyze_track(s, g, P, dom_codes=dc)
        kind = r["name"].rsplit("_", 1)[0]
        p = r["probability"]
        good = (p < 0.25) if kind == "human" else (p > 0.8)
        ok &= good
        print(f"{'OK ' if good else 'BAD'} {kind:<15} P={p:.3f}  ({verdict(p)})")
    print("self-test", "passed" if ok else "FAILED")
    return 0 if ok else 1


# --------------------------------------------------------------------------- #
def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__.split("\n\n")[0],
                                 formatter_class=argparse.RawDescriptionHelpFormatter,
                                 epilog=__doc__.split("\n\n", 1)[1])
    ap.add_argument("data", nargs="*", help="data dir, data/chat, a stream dir or .jsonl files")
    mode = ap.add_mutually_exclusive_group()
    mode.add_argument("--user", "-u", action="append",
                      help="channel ID, channel URL, @handle or display name (repeatable)")
    mode.add_argument("--rank", action="store_true", help="score every account with enough messages")
    mode.add_argument("--bots", nargs="?", type=float, const=0.8, metavar="MIN_P",
                      help="list only accounts that are likely bots (P >= MIN_P, default 0.8); "
                           "combine with --stream and --from/--to")
    mode.add_argument("--calibrate", metavar="LABELS.csv",
                      help="CSV rows 'account,label' (label 1/bot or 0/human); fits evidence weights")
    mode.add_argument("--selftest", action="store_true", help="run on simulated accounts and exit")
    ap.add_argument("--stream", action="append",
                    help="ICV, CV, CVC, CVC2 or a video id (repeatable; use --stream=-id for ids starting with -)")
    ap.add_argument("--from", dest="date_from", metavar="WHEN",
                    help="start: YYYY-MM-DD or 'YYYY-MM-DD HH:MM' (inclusive)")
    ap.add_argument("--to", dest="date_to", metavar="WHEN",
                    help="end: YYYY-MM-DD (whole day included) or 'YYYY-MM-DD HH:MM' (exclusive)")
    ap.add_argument("--tz", default="local",
                    help="time zone for --from/--to and printed times (default: this computer's; "
                         "e.g. Europe/Berlin, UTC). The logger names its files in local time.")
    ap.add_argument("--show-borderline", action="store_true", help="--bots: also list 0.5 <= P < MIN_P")
    ap.add_argument("--cooldown", type=float, help="override slow-mode seconds (unknown streams are estimated)")
    ap.add_argument("--min-messages", type=int, default=None,
                    help="--rank/--bots: minimum messages per account and stream in the window "
                         "(default 300 for --rank, 100 for --bots)")
    ap.add_argument("--top", type=int, default=40, help="--rank: rows to print")
    ap.add_argument("--prior", type=float, default=0.20, help="prior P(automated) for an active account")
    ap.add_argument("--session-gap", type=float, default=120.0, help="seconds of silence that end a session")
    ap.add_argument("--weights", help="JSON from --save-weights")
    ap.add_argument("--save-weights", help="--calibrate: where to write weights")
    ap.add_argument("--json", help="write full results as JSON")
    ap.add_argument("--csv", help="--rank/--bots: write table as CSV")
    ap.add_argument("--plot", help="--user: write diagnostic PNG (needs matplotlib)")
    ap.add_argument("--cache-dir", default=os.path.join(os.path.expanduser("~"), ".cache", "utonish-botscore"),
                    help="parsed-file cache (default ~/.cache/utonish-botscore)")
    ap.add_argument("--no-cache", action="store_true")
    args = ap.parse_args(argv)

    if args.selftest:
        return run_selftest()
    if not args.data:
        ap.error("give the data folder (or files)")
    if not (args.user or args.rank or args.calibrate or args.bots is not None):
        ap.error("choose --user, --bots, --rank or --calibrate")
    if args.min_messages is None:
        args.min_messages = 100 if args.bots is not None else 300
    if args.bots is not None and not 0 < args.bots < 1:
        ap.error("--bots threshold must be between 0 and 1, e.g. --bots 0.9")
    global DISPLAY_TZ
    DISPLAY_TZ = get_tz(args.tz)
    t_from = t_to = None
    day_from = day_to = None
    if args.date_from:
        t_from, day_from = parse_when(args.date_from, end=False, tz=DISPLAY_TZ)
    if args.date_to:
        t_to, day_to = parse_when(args.date_to, end=True, tz=DISPLAY_TZ)
    if t_from is not None and t_to is not None and t_to <= t_from:
        ap.error("--to must be after --from")
    window = (f"{fmt_t(t_from) if t_from else 'start of data'} -> "
              f"{fmt_t(t_to) if t_to else 'end of data'}")

    P = Params(prior=args.prior, session_gap=args.session_gap)
    if args.weights:
        with open(args.weights) as fh:
            wj = json.load(fh)
        P.weights, P.bias = wj.get("weights", {}), wj.get("bias")

    sel = {STREAM_ALIASES.get(x.lower(), x) for x in args.stream} if args.stream else None
    streams = load_streams(args.data, sel, day_from, day_to,
                           None if args.no_cache else args.cache_dir, args.cooldown,
                           t_from=t_from, t_to=t_to)
    for s in streams.values():
        print(f"  {s.name} ({s.sid}): {sum(len(t) for t, _ in s.users.values())} messages, "
              f"{len(s.users)} accounts, slow mode {s.cooldown:.0f}s", file=sys.stderr)

    if args.calibrate:
        run_calibrate(streams, P, args)
    elif args.bots is not None:
        run_bots(streams, P, args, window)
    elif args.rank:
        run_rank(streams, P, args)
    else:
        results = {}
        for q in args.user:
            results.update(run_user(streams, q, P, args))
        if args.json:
            js = {cid: [track_json(r) for r in tr] for cid, tr in results.items()}
            with open(args.json, "w", encoding="utf-8") as fh:
                json.dump(js, fh, ensure_ascii=False, indent=1, default=_json_default)
            print(f"JSON written to {args.json}", file=sys.stderr)
    return 0


if __name__ == "__main__":
    sys.exit(main())